  "implementation": "def solve(case):
    lines = case['lines']
    trajectory = []
    last_type = None
    error_line = None
    for i, line in enumerate(lines):
        line_num = i + 1
        colon_pos = line.find(':')
        if colon_pos == -1:
            error_line = line_num
            break
        prefix = line[:colon_pos].strip().lower()
        content = line[colon_pos+1:].strip()
        type_map = {
            'thought': 'thought',
            'action': 'action',
            'action input': 'action_input',
            'observation': 'observation',
            'final': 'final'
        }
        rec_type = type_map.get(prefix)
        if rec_type is None:
            error_line = line_num
            break
        allowed = []
        if last_type is None:
            allowed = ['thought', 'final']
        elif last_type == 'thought':
            allowed = ['action', 'final']
        elif last_type == 'action':
            allowed = ['observation', 'action_input']
        elif last_type == 'action_input':
            allowed = ['observation']
        elif last_type == 'observation':
            allowed = ['thought']
        elif last_type == 'final':
            allowed = []
        if rec_type not in allowed:
            error_line = line_num
            break
        trajectory.append({'type': rec_type, 'content': content})
        last_type = rec_type
    if error_line is not None:
        return {'error_line': error_line, 'trajectory': trajectory, 'valid': False}
    else:
        return {'error_line': None, 'trajectory': trajectory, 'valid': True}
